# If no user is specified (for RetroPie below v4.8.9)
if [[ -z "$__user" ]]; then __user="$SUDO_USER"; [[ -z "$__user" ]] && __user="$(id -un)"; fi

rp_module_id="tmnt-port"
rp_module_desc="Teenage Mutant Ninja Turtles - Port"
rp_module_licence="BSD3 https://raw.githubusercontent.com/cheviman/tmnt-port/main/LICENSE"
rp_module_repo="git https://github.com/cheviman/tmnt-port.git main"
rp_module_help="*TMNT ROM/ASSETS REQUIRED* (MAME's tmnt World 4 Player)

*1st RUN* OPEN in DESKTOP ENVIRONMENT* (F11 Fullscreen)
DRAG/DROP TMNT.ZIP ROM INTO PORT       (Alt+F4 to Quit)

Konami's 1989 arcade game Teenage Mutant Ninja Turtles
as a native game for computers, Raspberry Pi, Switch,
Android, iPhone and iPad, and Anbernic's handhelds.

TMNT: The Console Version, made for playing at home
TMNT Arcade: Arcade Version, Coins, Test Mode, 4Players

MULTIPLAYER: May Require Firewall Ports Allowed:
UDP *:32818 UDP *:27741

Built in C based on its Decompilation: tmntarcade-decomp"
rp_module_section="exp"

function depends_tmnt-port() {
    if ! isPlatform "64bit" ; then
        #dialog --ok --msgbox "Installer is for a 64bit system Only!" 22 76 2>&1 >/dev/tty
        md_ret_errors+=("$md_desc Installer is for a 64bit system Only!")
    fi

    local depends+=(cmake python3)
    ##depends+=(libsdl3-dev) # -DTMNT_STATIC_SDL=ON builds SDL 3.4.20 from its source into the game
    isPlatform "kms" && depends+=(xorg matchbox-window-manager)
    getDepends "${depends[@]}"
}

function sources_tmnt-port() {
    gitPullOrClone
}

function build_tmnt-port() {
    cmake -S . -B build/cmake -DTMNT_STATIC_SDL=ON
    cmake --build build/cmake --config Release
    md_ret_require="$md_build/build/bin/TMNT"
}

function install_tmnt-port() {
    md_ret_files=(
       'build/bin'
    )
}

function game_data_tmnt-port() {
    # Artwork and gamelist.xml
    if [[ ! -f "$romdir/ports/media/image/TMNT-Port.png" ]]; then
        downloadAndExtract "https://raw.githubusercontent.com/RapidEdwin08/RetroPie-Setup-Assets/main/ports/tmnt-port-rp-assets.tar.gz" "$romdir/ports"
        if [[ ! -f "$romdir/ports/gamelist.xml" ]] && [[ ! -f "/opt/retropie/configs/all/emulationstation/gamelists/ports/gamelist.xml" ]]; then mv "$romdir/ports/gamelist.xml.tmnt-port" "$romdir/ports/gamelist.xml"; fi
        chown -R $__user:$__user "$romdir/ports"
    fi
}

function remove_tmnt-port() {
    local shortcut_name
    shortcut_name="TMNT-Port"
    rm -f "/usr/share/applications/$shortcut_name.desktop"; rm -f "$home/Desktop/$shortcut_name.desktop" > /dev/null 2>&1
    rm -f "$romdir/ports/$shortcut_name.sh" > /dev/null 2>&1
}

function configure_tmnt-port() {
    mkRomDir "ports"

    addPort "$md_id" "tmnt-port" "TMNT-Port" "$md_inst/bin/TMNT"
    addPort "$md_id-arcade-4p" "tmnt-port" "TMNT-Port" "$md_inst/bin/TMNT Arcade"

    moveConfigDir "$home/.local/share/TMNT" "$md_conf_root/$md_id/TMNT"

    local config="$md_conf_root/$md_id/TMNT/tmnt.ini"
    if [[ "$md_mode" == "install" ]]; then
        touch "$config"
        iniConfig "=" '' "$config"

        iniSet "full_screen" "1"
        iniSet "vsync" "1"
        iniSet "name" "D00MGUY"

        chown $__user:$__user "$config"
    fi

    [[ "$md_mode" == "remove" ]] && remove_tmnt-port
    [[ "$md_mode" == "remove" ]] && return
    [[ "$md_mode" == "install" ]] && game_data_tmnt-port
    [[ "$md_mode" == "install" ]] && shortcuts_icons_tmnt-port
}

function shortcuts_icons_tmnt-port() {
    local shortcut_name
    shortcut_name="TMNT-Port"
    cat >"$md_inst/$shortcut_name.desktop" << _EOF_
[Desktop Entry]
Name=$shortcut_name
GenericName=$shortcut_name
Comment=$shortcut_name
Exec=$md_inst/bin/TMNT
Icon=$md_inst/tmnt-port_96x96.xpm
Terminal=false
Type=Application
Categories=Game;Port
Keywords=TMNT;Port
StartupWMClass=TMNT-Port
Name[en_US]=$shortcut_name
_EOF_
    chmod 755 "$md_inst/$shortcut_name.desktop"
    if [[ -d "$home/Desktop" ]]; then rm -f "$home/Desktop/$shortcut_name.desktop"; cp "$md_inst/$shortcut_name.desktop" "$home/Desktop/$shortcut_name.desktop"; chown $__user:$__user "$home/Desktop/$shortcut_name.desktop"; fi
    rm -f "/usr/share/applications/$shortcut_name.desktop"; cp "$md_inst/$shortcut_name.desktop" "/usr/share/applications/$shortcut_name.desktop"; chown $__user:$__user "/usr/share/applications/$shortcut_name.desktop"

    cat >"$md_inst/tmnt-port_96x96.xpm" << _EOF_
